_COMPILED = [(re.compile(p), r) for p, r in PATTERNS]
TREND_AR = {"increasing": "متزايد", "decreasing": "متناقص", "stable": "مستقر", "volatile": "متذبذب", "mostly increasing": "متزايد غالباً",
            "mostly decreasing": "متناقص غالباً", "insufficient data": "بيانات غير كافية"}


def tr(s, lang: str):
    """Translate one server sentence (or a few joined sentences) to Arabic; English passes through unchanged."""
    if lang != "ar" or not isinstance(s, str) or not s:
        return s
    if s in EXACT:
        return EXACT[s]
    if s in TREND_AR:
        return TREND_AR[s]
    for rx, rep in _COMPILED:
        if rx.match(s):
            return rx.sub(rep, s)
    # several sentences joined with spaces: translate each one
    parts = re.split(r"(?<=[.?])\s+(?=[A-Z'(])", s)
    if len(parts) > 1:
        return " ".join(tr(p, lang) for p in parts)
    return s


def tr_obs(o: dict, lang: str) -> dict:
    if lang != "ar":
        return o
    o = dict(o)
    for k in ("type_label", "area", "title", "finding", "reasoning", "possible_explanation", "financial_impact", "required_action", "question", "confidence"):
        if o.get(k):
            o[k] = tr(o[k], lang)
    return o
